/* From Uiverse.io by krlozCJ - Tags: neumorphism, login, form */
.__UIV_SCOPE__ .container {
  width: 300px;
  position: relative;
  border-radius: 5px;
  overflow: hidden;
  box-shadow: 1.5px 1.5px 3px #0e0e0e, -1.5px -1.5px 3px rgb(95 94 94 / 25%), inset 0px 0px 0px #0e0e0e, inset 0px -0px 0px #5f5e5e;
}

.__UIV_SCOPE__ .container .slider {
  width: 200%;
  position: relative;
  transition: transform ease-out 0.3s;
  display: flex;
}

.__UIV_SCOPE__ #register_toggle {
  display: none;
}

.__UIV_SCOPE__ .container #register_toggle:checked + .slider {
  transform: translateX(-50%);
}

.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 30px;
  padding: 1.5em 3em;
  width: 50%;
}

.__UIV_SCOPE__ .title {
  text-align: center;
  font-weight: 700;
  font-size: 2em;
}

.__UIV_SCOPE__ form .form_control {
  width: 100%;
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ form .form_control .label {
  position: absolute;
  top: 50%;
  left: 10px;
  transition: transform ease 0.2s;
  transform: translate(0%, -50%);
  font-size: 0.75em;
  user-select: none;
  pointer-events: none;
  color: #b0b0b0;
}

.__UIV_SCOPE__ form .form_control .input {
  width: 100%;
  background-color: transparent;
  border: none;
  outline: none;
  color: #fff;
  padding: 0.5rem;
  font-size: 0.75rem;
  border-radius: 5px;
  transition: box-shadow ease 0.2s;
  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 1.5px 1.5px 3px #0e0e0e, inset -1.5px -1.5px 3px #5f5e5e;
}

.__UIV_SCOPE__ form .form_control .input:focus,
.__UIV_SCOPE__ form .form_control .input:valid {
  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 3px 3px 4px #0e0e0e, inset -3px -3px 4px #5f5e5e;
}

.__UIV_SCOPE__ form .form_control .input:focus + .label,
.__UIV_SCOPE__ form .form_control .input:valid + .label {
  transform: translate(-150%, -50%);
}

.__UIV_SCOPE__ form button {
  width: 100%;
  background-color: transparent;
  border: none;
  outline: none;
  color: #fff;
  padding: 0.5rem;
  font-size: 0.75rem;
  border-radius: 5px;
  transition: box-shadow ease 0.1s;
  box-shadow: 1.5px 1.5px 3px #0e0e0e, -1.5px -1.5px 3px rgb(95 94 94 / 25%), inset 0px 0px 0px #0e0e0e, inset 0px -0px 0px #5f5e5e;
}

.__UIV_SCOPE__ form button:active {
  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 3px 3px 4px #0e0e0e, inset -3px -3px 4px #5f5e5e;
}

.__UIV_SCOPE__ .bottom_text {
  font-size: 0.65em;
}

.__UIV_SCOPE__ .bottom_text .swtich {
  font-weight: 700;
  cursor: pointer;
}
